define([],function(){return{init:function(cmid,showText,hideText){document.querySelectorAll('.personalityfinder-redo-link').forEach(function(link){link.addEventListener('click',function(event){if(!window.confirm(link.getAttribute('data-confirm-message'))){event.preventDefault();}});});var root=document.querySelector('.path-mod-personalityfinder #intro.activity-description');if(!root){return;}root.setAttribute('data-personalityfinder-description',cmid);var storageKey='mod_personalityfinder_description_visible_'+cmid;var showLabel=showText;var hideLabel=hideText;var button=document.querySelector('.personalityfinder-description-toggle[data-cmid="'+cmid+'"]');if(!button){button=document.createElement('button');button.type='button';button.className='btn btn-secondary btn-sm personalityfinder-description-toggle';button.setAttribute('data-cmid',cmid);root.insertAdjacentElement('afterend',button);}var setVisible=function(visible){root.hidden=!visible;button.setAttribute('aria-expanded',visible ? 'true':'false');button.textContent=visible ? hideLabel:showLabel;try{window.localStorage.setItem(storageKey,visible ? '1':'0');}catch(e){}};try{var saved=window.localStorage.getItem(storageKey);setVisible(saved !=='0');}catch(e){setVisible(true);}button.addEventListener('click',function(){setVisible(root.hidden);});}};});